def parseImpl(self, instring, loc, do_actions=True) -> ParseImplReturnType:
    maxExcLoc = -1
    maxException = None
    matches: list[tuple[int, ParserElement]] = []
    fatals: list[ParseFatalException] = []
    if all(e.callPreparse for e in self.exprs):
        loc = self.preParse(instring, loc)
    for e in self.exprs:
        try:
            loc2 = e.try_parse(instring, loc, raise_fatal=True)
        except ParseFatalException as pfe:
            pfe.__traceback__ = None
            pfe.parser_element = e
            fatals.append(pfe)
            maxException = pfe
            maxExcLoc = pfe.loc
        except ParseException as err:
            if not fatals:
                err.__traceback__ = None
                if err.loc < maxExcLoc:
                    maxException = err
                    maxExcLoc = err.loc
        except IndexError:
            if len(instring) <= maxExcLoc:
                maxException = ParseException(
                    instring, len(instring), e.errmsg, self
                )
                maxExcLoc = len(instring)
        else:
            matches.append((loc2, e))

    if matches:
        matches.sort(key=itemgetter(0), reverse=True)

        if not do_actions:
            best_expr = matches[0][1]
            return best_expr._parse(instring, loc, do_actions)

        longest: tuple[int, typing.Optional[ParseResults]] = -1, None
        for loc1, expr1 in matches:
            if loc1 < longest[0]:
                return longest

            try:
                loc2, toks = expr1._parse(instring, loc, do_actions)
            except ParseException as err:
                err.__traceback__ = None
                if err.loc < maxExcLoc:
                    maxException = err
                    maxExcLoc = err.loc
            else:
                if loc2 <= loc1:
                    return loc2, toks
                elif loc2 < longest[0]:
                    longest = loc2, toks

        if longest != (-1, None):
            return longest

    if fatals:
        if len(fatals) > 1:
            fatals.sort(key=lambda e: -e.loc)
            if fatals[0].loc == fatals[1].loc:
                fatals.sort(key=lambda e: (-e.loc, len(str(e.parser_element))))
        max_fatal = fatals[-1]
        raise max_fatal

    if maxException is not None:
        if maxExcLoc != loc:
            maxException.msg = self.errmsg or ""
        raise maxException

    raise IndexError(f"Unexpected end of {instring}")

